<docs>
Use this screen at the end of your experiment to submit the data to the server.
You can provide the submission URL to the Experiment component.
</docs>

<template>
  <Screen v-if="!$magpie.debug" title="Datenübertragung">
    <Slide>
      <div class="submission-content">
        <p>{{ $t('screens.SubmitResultsScreen.waiting') }}</p>
        <Wait :time="0" @done="submit()" />
      </div>
    </Slide>

    <Slide>
      <div v-if="!error" class="submission-content">
        <h2>Vielen Dank für deine Teilnahme!</h2>

        <p>
          Deine Antworten wurden erfolgreich übermittelt.
        </p>

        <p>
          Dein persönlicher Abschlusscode lautet:
        </p>

        <p class="completion-code">
          {{ completionCode }}
        </p>

        <p>
          Um deine Aufwandsentschädigung zu erhalten, schreibe bitte eine
          E-Mail an
          <a :href="emailLink">
            {{ researcherEmail }}
          </a>
          und gib deinen Abschlusscode in der Nachricht an.
        </p>

        <p>
          Anschließend erhältst du per E-Mail eine Teilnahmebescheinigung.
          Bitte fülle diese aus, unterschreibe sie und sende sie per E-Mail
          zurück. Sobald die unterschriebene Teilnahmebescheinigung bei uns
          eingegangen ist, wird dir dein Gutschein zugesendet.
        </p>
      </div>

      <div v-else class="submission-content error-content">
        <h2>Fehler bei der Datenübertragung</h2>

        <p>
          Deine Antworten konnten leider nicht erfolgreich übermittelt
          werden.
        </p>

        <p>
          Bitte wende dich an
          <a :href="'mailto:' + $magpie.contactEmail">
            {{ $magpie.contactEmail }}
          </a>.
        </p>

        <p v-text="error" />
      </div>
    </Slide>
  </Screen>

  <DebugResultsScreen v-else />
</template>

<script>
import Screen from '../Screen';
import Wait from '../helpers/Wait';
import DebugResultsScreen from './DebugResultsScreen';
import Slide from '../Slide';

export default {
  name: 'SubmitResultsScreen',

  components: {
    Screen,
    Slide,
    Wait,
    DebugResultsScreen
  },

  data() {
    return {
      error: null,
      completionCode: '',
      researcherEmail: 'gemma.seghi@uni-tuebingen.de'
    };
  },

  computed: {
    emailLink() {
      const subject = encodeURIComponent(
        'Abschluss der Studie und Aufwandsentschädigung'
      );

      const body = encodeURIComponent(
        `Hallo,\n\n` +
          `ich habe das Experiment abgeschlossen.\n\n` +
          `Mein Abschlusscode lautet: ${this.completionCode}\n\n` +
          `Bitte senden Sie mir die Teilnahmebescheinigung zu.\n\n` +
          `Viele Grüße`
      );

      return (
        `mailto:${this.researcherEmail}` +
        `?subject=${subject}` +
        `&body=${body}`
      );
    }
  },

  created() {
    this.completionCode = this.getOrCreateCompletionCode();

    this.$magpie.addExpData({
      recruitment_source: 'paid',
      payment_completion_code: this.completionCode
    });
  },

  methods: {
    getOrCreateCompletionCode() {
      const storageKey = 'study-72-paid-completion-code';

      const existingCode =
        window.sessionStorage.getItem(storageKey);

      if (existingCode) {
        return existingCode;
      }

      let randomPart;

      if (
        window.crypto &&
        typeof window.crypto.getRandomValues === 'function'
      ) {
        const randomBytes = new Uint8Array(8);
        window.crypto.getRandomValues(randomBytes);

        randomPart = Array.from(randomBytes)
          .map((byte) =>
            byte.toString(16).padStart(2, '0')
          )
          .join('')
          .toUpperCase();
      } else {
        randomPart = (
          Date.now().toString(36) +
          Math.random().toString(36).slice(2)
        )
          .slice(0, 16)
          .toUpperCase();
      }

      const code = `PAID-${randomPart}`;

      window.sessionStorage.setItem(storageKey, code);

      return code;
    },

    async submit() {
      try {
        await this.$magpie.submit();

        this.disableUnloadWarning();
        this.$magpie.nextSlide();
      } catch (err) {
        this.error =
          err instanceof Error
            ? err.message
            : String(err);

        this.$magpie.nextSlide();
      }
    },

    disableUnloadWarning() {
      const experiment = this.$magpie.experiment;

      if (
        experiment &&
        typeof experiment.disableBeforeUnload === 'function'
      ) {
        experiment.disableBeforeUnload();
      }
    }
  }
};
</script>

